-- Run only against an explicitly selected disposable local database. Every fixture is rolled back.
begin;
select set_config('request.jwt.claim.role','service_role',true);
do $$
<<eps_payment_gateway>>
declare customer_id uuid; admin_id uuid; warehouse_id uuid; product_id uuid:=gen_random_uuid(); address_id uuid:=gen_random_uuid(); cart_id uuid; operation_id uuid:=gen_random_uuid(); order_id uuid; second_order uuid; abandoned_order uuid; review_order uuid; result jsonb; attempt_id uuid; attempt2 uuid; review_attempt uuid; payment_result text; rejected boolean:=false; before_payments bigint; before_journals bigint;
begin
  select id into customer_id from public.profiles where email='mobile.customer@example.test';
  select id into admin_id from public.profiles where email='mobile.admin@example.test';
  insert into public.warehouses(code,name,country_code,country_name) values('EPS-TEST-'||gen_random_uuid(),'EPS rollback warehouse','BD','Bangladesh') returning id into warehouse_id;
  if customer_id is null or admin_id is null then raise exception 'Required local fixtures are unavailable'; end if;
  update public.payment_gateways set enabled=true,test_mode=true where code='eps';
  update public.shopping_carts set status='abandoned' where profile_id=customer_id and status='active';
  insert into public.products(id,name,slug,sku,status,currency,regular_price,public_catalogue_visible,default_warehouse_id)
  values(product_id,'EPS rollback test product','eps-test-'||product_id,'EPS-TEST-'||product_id,'active','BDT',120.50,true,warehouse_id);
  insert into public.inventory_balances(product_id,warehouse_id,on_hand,reserved) values(product_id,warehouse_id,10,0);
  insert into public.customer_addresses(id,profile_id,recipient_name,phone,address_line_1,city,region,postal_code,country_code)
  values(address_id,customer_id,'Local Test','01700000000','Local test address','Dhaka','Dhaka','1200','BD');
  insert into public.shopping_carts(profile_id,currency) values(customer_id,'BDT') returning id into cart_id;
  insert into public.shopping_cart_items(cart_id,product_id,quantity) values(cart_id,product_id,1);
  rejected:=false;
  begin perform public.customer_checkout_cart_eps(customer_id,address_id,'Local sandbox test','test@example.test','01700000000',gen_random_uuid(),repeat('f',64),120.49); exception when others then rejected:=true; end;
  if not rejected then raise exception 'Changed review amount did not block checkout'; end if;
  rejected:=false;
  order_id:=public.customer_checkout_cart_eps(customer_id,address_id,'Local sandbox test','test@example.test','01700000000',operation_id,repeat('a',64),120.50);
  if public.customer_checkout_cart_eps(customer_id,address_id,'Local sandbox test','test@example.test','01700000000',operation_id,repeat('a',64),120.50)<>order_id then raise exception 'Checkout replay duplicated order'; end if;
  if (select reserved from public.inventory_balances where inventory_balances.product_id=eps_payment_gateway.product_id) is distinct from 1::numeric then raise exception 'Checkout did not reserve inventory'; end if;
  rejected:=false;
  begin perform public.begin_eps_payment(order_id,admin_id,'202611230000009'); exception when others then rejected:=true; end;
  if not rejected then raise exception 'Another account initiated payment for this customer'; end if;
  rejected:=false;
  result:=public.begin_eps_payment(order_id,customer_id,'202611230000001');attempt_id:=(result->'attempt'->>'id')::uuid;
  if (public.begin_eps_payment(order_id,customer_id,'202611230000002')->>'created')::boolean then raise exception 'Repeated initiation created another attempt'; end if;
  begin perform public.apply_eps_verification(attempt_id,'202611230000001',120.49,'success','TEST-SANDBOX','test',admin_id); exception when others then rejected:=true; end;
  if not rejected then raise exception 'Wrong amount was accepted'; end if;
  select count(*) into before_payments from public.sale_payments;select count(*) into before_journals from public.journal_entries;
  payment_result:=public.apply_eps_verification(attempt_id,'202611230000001',120.50,'success','TEST-SANDBOX','test',admin_id);
  if payment_result<>'sandbox_paid' or (select paid_amount from public.sales_orders where id=order_id)<>0 then raise exception 'Sandbox changed real order totals'; end if;
  if (select count(*) from public.sale_payments)<>before_payments or (select count(*) from public.journal_entries)<>before_journals then raise exception 'Sandbox created real income'; end if;
  update public.payment_gateways set test_mode=false where code='eps';
  insert into public.shopping_carts(profile_id,currency) values(customer_id,'BDT') returning id into cart_id;
  insert into public.shopping_cart_items(cart_id,product_id,quantity) values(cart_id,product_id,1);
  second_order:=public.customer_checkout_cart_eps(customer_id,address_id,'Local simulated live settlement','test@example.test','01700000000',gen_random_uuid(),repeat('b',64),120.50);
  result:=public.begin_eps_payment(second_order,customer_id,'202611230000003');attempt2:=(result->'attempt'->>'id')::uuid;
  payment_result:=public.apply_eps_verification(attempt2,'202611230000003',120.50,'success','TEST-LIVE-NO-EXTERNAL-PAYMENT','test',admin_id);
  if payment_result<>'paid' or (select paid_amount from public.sales_orders where id=second_order)<>120.50 then raise exception 'Verified live settlement did not pay order'; end if;
  perform public.apply_eps_verification(attempt2,'202611230000003',120.50,'success','TEST-LIVE-NO-EXTERNAL-PAYMENT','test',admin_id);
  perform public.apply_eps_verification(attempt2,'202611230000003',120.50,'failed',null,'test',admin_id);
  if (select count(*) from public.sale_payments where sale_payments.order_id=second_order)<>1 then raise exception 'Callback replay duplicated payment'; end if;
  if (select a.status from public.eps_payment_attempts a where a.id=attempt2)<>'paid' then raise exception 'Older failure downgraded paid result'; end if;
  if (select sum(debit-credit) from public.journal_lines where journal_entry_id=(select journal_entry_id from public.eps_payment_attempts where id=attempt2))<>0 then raise exception 'EPS journal is unbalanced'; end if;
  if exists(select 1 from public.cashbook_entries where sale_payment_id=(select sale_payment_id from public.eps_payment_attempts where id=attempt2)) then raise exception 'Unsettled EPS funds entered cashbook'; end if;
  insert into public.shopping_carts(profile_id,currency) values(customer_id,'BDT') returning id into cart_id;
  insert into public.shopping_cart_items(cart_id,product_id,quantity) values(cart_id,product_id,1);
  abandoned_order:=public.customer_checkout_cart_eps(customer_id,address_id,'Expired local test','test@example.test','01700000000',gen_random_uuid(),repeat('c',64),120.50);
  update public.eps_checkout_requests set payment_expires_at=now()-interval '1 minute' where eps_checkout_requests.order_id=abandoned_order;
  perform public.expire_eps_unpaid_orders(admin_id);
  if (select o.status from public.sales_orders o where o.id=abandoned_order)<>'cancelled' then raise exception 'Abandoned checkout did not expire'; end if;
  if (select b.reserved from public.inventory_balances b where b.product_id=eps_payment_gateway.product_id)<>2 then raise exception 'Expired checkout did not release exactly its own stock'; end if;
  insert into public.shopping_carts(profile_id,currency) values(customer_id,'BDT') returning id into cart_id;
  insert into public.shopping_cart_items(cart_id,product_id,quantity) values(cart_id,product_id,1);
  review_order:=public.customer_checkout_cart_eps(customer_id,address_id,'Changed order payment review test','test@example.test','01700000000',gen_random_uuid(),repeat('d',64),120.50);
  result:=public.begin_eps_payment(review_order,customer_id,'202611230000005');review_attempt:=(result->'attempt'->>'id')::uuid;
  update public.sales_orders set total_amount=120.49 where id=review_order;
  rejected:=false;
  begin perform public.begin_eps_payment(review_order,customer_id,'202611230000006'); exception when others then rejected:=true; end;
  if not rejected then raise exception 'Changed outstanding amount resumed stale payment'; end if;
  payment_result:=public.apply_eps_verification(review_attempt,'202611230000005',120.50,'success','TEST-REVIEW-NO-EXTERNAL-PAYMENT','test',admin_id);
  if payment_result<>'review_required' or exists(select 1 from public.sale_payments where sale_payments.order_id=review_order) then raise exception 'Changed outstanding amount was settled'; end if;
  payment_result:=public.apply_eps_verification(review_attempt,'202611230000005',120.50,'failed',null,'test',admin_id);
  if payment_result<>'review_required' then raise exception 'Late failure erased received-payment review'; end if;
  payment_result:=public.apply_eps_verification(review_attempt,'202611230000005',120.50,'pending',null,'test',admin_id);
  if payment_result<>'review_required' then raise exception 'Late pending erased received-payment review'; end if;
  if has_function_privilege('authenticated','public.apply_eps_verification(uuid,text,numeric,text,text,text,uuid)','execute') or has_table_privilege('anon','public.eps_payment_attempts','select') then raise exception 'Untrusted role can access payment internals'; end if;
  perform set_config('request.jwt.claim.role','authenticated',true);rejected:=false;
  begin perform public.begin_eps_payment(order_id,customer_id,'202611230000004'); exception when others then rejected:=true; end;
  if not rejected then raise exception 'Untrusted role reached initiation RPC'; end if;
  raise notice 'PASS: checkout idempotency, review amount guard, inventory reservation, amount validation, sandbox isolation, live settlement, callback replay, balanced clearing ledger, no false cashbook receipt, abandoned checkout expiry, service-only permissions';
end $$;
rollback;
